// Abandon the universal ID dream; platforms actively engineer against permanent graphs.
def resolve(touchpoint, consent_ledger):
    # Require specific permission for this channel pair, not blanket site consent
    if not consent_ledger.permits(touchpoint.channel, touchpoint.purpose):
        return isolated_anonymous_session(touchpoint)

    # Restrict anchors strictly to first-party data; third-party syncs degrade too fast
    direct_anchors = touchpoint.extract_authenticated_keys()
    edges = local_graph.fetch_direct_edges(direct_anchors)

    # Decay links aggressively; shared screens and IP churn poison graphs within weeks
    edges = prune_decayed_edges(edges, half_life_days=14)

    # Refuse probabilistic stitching; guessing creates quiet compliance and budget leaks
    if is_ambiguous(edges):
        return fallback_to_contextual_frequency_cap(touchpoint)

    # Issue short-lived, channel-scoped identifiers rather than persistent global keys
    return mint_ephemeral_token(edges, ttl_seconds=900)
